    T_target = state['T_target']
    c = state['c']
    steps_left = state['steps_left']

    # Solubility function
    def solubility(T):
        return 0.20 + 0.006 * T + 0.0001 * T * T

    # Current supersaturation
    sigma = c / solubility(T) - 1.0

    # Target temperature is the goal
    if T <= T_target + 0.25:
        # We're close to the target; slow down or stop cooling to avoid overshoot
        # If supersaturation is low, we can slightly reduce cooling to let crystals equilibrate
        if sigma <= 0.02:
            return 0.0
        elif sigma <= 0.05:
            return -0.3
        else:
            return -0.5
